<script setup lang="ts">
import { ref } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { get,post } from '../api/client'
import type { Run,Model } from '../api/types'
import { session,allowed } from '../composables/session'
import { useQuery } from '../composables/useQuery'
import { useCursorList } from '../composables/useCursorList'
import { useMutation } from '../composables/useMutation'
import { count,date,short } from '../api/format'
import PageHeader from '../components/PageHeader.vue'
import Icon from '../components/Icon.vue'
import Feedback from '../components/Feedback.vue'
import StatusBadge from '../components/StatusBadge.vue'
import JsonView from '../components/JsonView.vue'
import ResourceTable from '../components/ResourceTable.vue'
import PrepareForm from '../components/PrepareForm.vue'
import Modal from '../components/Modal.vue'
const route=useRoute(),router=useRouter(),id=String(route.params.id),root=`/projects/${session.project!.id}`,tab=ref(route.query.tab==='quality'?'quality':'overview'),op=useMutation(),preparing=ref(false),intent=ref('rollback'),prepId=ref(typeof route.query.preparation==='string'?route.query.preparation:'')
const q=useQuery(s=>get<Run>(`/api/v1/execution-runs/${id}`,s),[],5000)
const logList=useCursorList<Model<'LogEntryResponse'>>(`/api/v1/execution-runs/${id}/logs`,5000),logs=logList.q
const diagnostic=useQuery(s=>get<Model<'DiagnosticReportResponse'>|null>(`/api/v1/execution-runs/${id}/diagnostic-report`,s))
const operationList=useCursorList<Model<'RunOperationResponse'>>(`/api/v1/execution-runs/${id}/operations`,5000),operations=operationList.q
async function operation(kind:string){if(!q.data.value||!window.confirm(`确认申请${{cancel:'取消',pause:'暂停',resume:'恢复',rollback:'回滚',rerun:'重跑'}[kind as 'cancel']}？运行 ${short(id)}。操作结果以引擎核验为准。`))return;const run=q.data.value.run;q.invalidate();await op.run(async()=>{if(['rollback','rerun'].includes(kind)&&!prepId.value)throw new Error('必须先申请并批准新的准备单');const r=await post<Model<'RunOperationResponse'>|Model<'CommitAcceptedResponse'>>(`/api/v1/execution-runs/${id}/${kind}`,{expected_revision:run.revision,...(kind==='rollback'?{preparation_id:prepId.value,publication_id:q.data.value!.publication?.status==='published'?q.data.value!.publication.id:null}:kind==='rerun'?{preparation_id:prepId.value,original_run_id:id}:{})},{key:crypto.randomUUID()});if(kind==='rerun'&&'execution_run_id'in r.data)await router.push(`${root}/runs/${r.data.execution_run_id}`);return r});await q.refresh();await operations.refresh()}
function begin(kind:string){intent.value=kind;preparing.value=true}
function prepared(preparation:string){void router.push(`${root}/preparations/${preparation}${intent.value==='rerun'?`?rerunOf=${id}`:''}`)}
</script>
<template><PageHeader eyebrow="EXECUTION, WITH EVIDENCE" title="运行详情" :description="`运行 ${id}`"><button class="button" @click="q.refresh();logs.refresh();operations.refresh();diagnostic.refresh()"><Icon name="refresh" :size="15"/>核实当前事实</button></PageHeader><Feedback :error="q.error.value||op.error.value" :notice="op.notice.value" :loading="q.loading.value" :unknown="op.unknown.value" @retry="q.refresh()"/><template v-if="q.data.value"><section class="card"><div class="card-heading"><div><h2>执行与发布快照</h2><p>{{date(q.data.value.run.started_at)}} · 引擎作业 {{q.data.value.run.engine_job_id||'尚未取得标识'}}</p></div><div class="actions"><StatusBadge :value="q.data.value.run.execution_status"/><StatusBadge :value="q.data.value.publication?.status||'not_published'"/></div></div><div class="card-body"><div class="actions"><RouterLink :to="`${root}/versions/${q.data.value.run.version_id}`" class="button small">查看冻结版本</RouterLink><RouterLink :to="`${root}/preparations/${q.data.value.run.preparation_id}`" class="button small">查看原准备单</RouterLink><button v-for="action in ['cancel','pause','resume']" :key="action" class="button small" :class="{danger:action==='cancel'}" :disabled="!allowed(action,q.data.value.available_actions)||op.busy.value||op.unknown.value" @click="operation(action)">{{{cancel:'请求取消',pause:'请求暂停',resume:'请求恢复'}[action as 'cancel']}}</button><button class="button small" :disabled="!allowed('rollback',q.data.value.available_actions)" @click="begin('rollback')">申请新回滚准备</button><button class="button small" :disabled="!allowed('rerun',q.data.value.available_actions)" @click="begin('rerun')">申请安全重跑</button></div><div v-if="prepId" class="block-note"><p>已关联新准备：<RouterLink :to="`${root}/preparations/${prepId}`">{{prepId}} ↗</RouterLink></p><button class="button small" :disabled="!allowed(route.query.intent==='rerun'?'rerun':'rollback',q.data.value.available_actions)||op.busy.value||op.unknown.value" @click="operation(route.query.intent==='rerun'?'rerun':'rollback')">使用新准备提交{{route.query.intent==='rerun'?'重跑':'回滚'}}</button></div></div></section><div class="stats-grid section-space"><article v-for="metric in [['读取记录',q.data.value.run.input_records],['有效写入',q.data.value.run.output_records],['错误记录',q.data.value.run.error_records],['处理字节',q.data.value.run.bytes_processed]]" :key="String(metric[0])" class="card stat-card"><div class="stat-top">{{metric[0]}}<Icon name="activity" :size="15"/></div><div class="stat-number">{{count(metric[1])}}</div><div class="stat-bottom">null 表示尚未获得可靠观测</div></article></div><div class="tabs" role="tablist"><button v-for="t in [['overview','监督与发布'],['logs','平台日志'],['quality','质量报告'],['diagnostic','诊断证据'],['operations','操作记录']]" :key="t[0]" role="tab" :aria-selected="tab===t[0]" :class="{selected:tab===t[0]}" @click="tab=t[0]!">{{t[1]}}</button></div><div v-if="tab==='overview'" class="detail-grid"><section class="card"><div class="card-heading"><h2>运行监督</h2><StatusBadge :value="q.data.value.supervision?.decision||'unknown'"/></div><div class="card-body"><JsonView :value="q.data.value.supervision"/></div></section><section class="card"><div class="card-heading"><h2>原子发布与恢复</h2></div><div class="card-body"><JsonView :value="{publication:q.data.value.publication,latest_rollback:q.data.value.latest_rollback}"/></div></section></div><section v-if="tab==='logs'" class="card"><div class="card-heading"><div><h2>控制面安全事件日志</h2><p>当前为平台审计投影，不冒充真实引擎日志。按服务端游标分页，每页20项。</p></div></div><Feedback :error="logs.error.value"/><div class="card-body"><JsonView :value="logs.data.value?.items" code/></div><div class="pagination"><span>第 {{logList.stack.value.length}} 段</span><div><button class="button small" :disabled="logList.stack.value.length===1" @click="logList.previous">上一段</button><button class="button small" :disabled="!logs.data.value?.has_more" @click="logList.next">下一段</button></div></div></section><section v-if="tab==='quality'" class="card"><div class="card-heading"><h2>质量报告</h2><StatusBadge :value="q.data.value.quality_report?.result||'unknown'"/></div><div class="card-body"><p class="block-note">通过与可发布结论均来自服务端。规则命中次数不能相加冒充违规总行数。</p><JsonView :value="q.data.value.quality_report"/></div></section><section v-if="tab==='diagnostic'" class="card"><div class="card-heading"><h2>可核实的诊断证据</h2></div><div class="card-body"><Feedback :error="diagnostic.error.value"/><JsonView :value="diagnostic.data.value"/></div></section><section v-if="tab==='operations'" class="card"><div class="card-heading"><h2>操作历史</h2></div><Feedback :error="operations.error.value"/><ResourceTable :rows="operations.data.value?.items||[]" :columns="[{key:'kind',label:'操作'},{key:'status',label:'操作状态',kind:'status'},{key:'created_at',label:'申请时间',kind:'date'},{key:'id',label:'记录标识',kind:'id'}]"/><div class="pagination"><span>第 {{operationList.stack.value.length}} 段</span><div><button class="button small" :disabled="operationList.stack.value.length===1" @click="operationList.previous">上一段</button><button class="button small" :disabled="!operations.data.value?.has_more" @click="operationList.next">下一段</button></div></div></section><Modal :open="preparing" :title="intent==='rollback'?'重新申请回滚授权':'为安全重跑申请新准备'" @close="preparing=false"><PrepareForm v-if="preparing" :version-id="q.data.value.run.version_id" :purpose="intent==='rollback'?'rollback':'execute_etl'" :run-id="intent==='rollback'?id:undefined" @created="prepared"/></Modal></template></template>
